with a as(select * from public.authors where open_library_id=any(array['OL228968A','OL8007250A','OL8007853A']::text[]) or id=any(array[]::bigint[])) select jsonb_build_object('checked_at',clock_timestamp(),'authors',(select coalesce(jsonb_agg(to_jsonb(t) order by id),'[]') from a t),'author_corpora',(select coalesce(jsonb_agg(to_jsonb(t) order by id),'[]') from public.works t where author_id in(select id from a)),'isbn_matches',(select coalesce(jsonb_agg(to_jsonb(t) order by id),'[]') from public.editions t where regexp_replace(coalesce(isbn_13,''),'[-[:space:]]','','g')=any(array['9789027432858','9789027414854']::text[])),'source_work_matches',(select coalesce(jsonb_agg(to_jsonb(t) order by id),'[]') from public.works t where open_library_id=any(array['OL1911336W']::text[])),'title_matches',(select coalesce(jsonb_agg(jsonb_build_object('relation','works','row',to_jsonb(t))),'[]') from public.works t where regexp_replace(lower(normalize(title,NFD)),'[^a-z0-9]','','g')=any(array['thedayofthetriffids','detriffidskomen']::text[])),'edition_title_matches',(select coalesce(jsonb_agg(jsonb_build_object('relation','editions','row',to_jsonb(t))),'[]') from public.editions t where regexp_replace(lower(normalize(title,NFD)),'[^a-z0-9]','','g')=any(array['thedayofthetriffids','detriffidskomen']::text[])),'reserved_test_ranges',jsonb_build_object('works',(select count(*) from public.works where id between 987124001 and 987124999),'editions',(select count(*) from public.editions where id between 987224001 and 987224999),'authors',(select count(*) from public.authors where id between 987324001 and 987324999))) as preflight;
